<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/functions.php';
requireRole(['admin']);
$totals = fetchOne("SELECT COUNT(*) FILTER (WHERE p.status = 'success') AS successful_count,
    COALESCE(SUM(b.gross_minor) FILTER (WHERE p.status = 'success'),0) AS gross_minor,
    COALESCE(SUM(b.commission_minor) FILTER (WHERE p.status = 'success'),0) AS commission_minor,
    COALESCE(SUM(p.provider_fee_minor) FILTER (WHERE p.status = 'success'),0) AS fee_minor,
    COUNT(*) FILTER (WHERE p.status IN ('pending','initializing')) AS pending_count,
    COUNT(*) FILTER (WHERE p.status = 'failed') AS failed_count
    FROM MarketplacePayments_007 p JOIN BookingOrders_007 b ON b.booking_id = p.booking_id");
$rows = fetchAll("SELECT p.transaction_reference, p.status, p.provider_fee_minor, p.created_at, b.booking_reference, b.gross_minor, b.commission_minor, b.organizer_net_minor, b.status AS booking_status,
    e.event_name, o.full_name AS organizer, a.full_name AS attendee
    FROM MarketplacePayments_007 p JOIN BookingOrders_007 b ON b.booking_id = p.booking_id
    JOIN Events_007 e ON e.event_id = b.event_id JOIN Organizers_007 o ON o.organizer_id = b.organizer_id
    JOIN Attendees_007 a ON a.attendee_id = b.attendee_id ORDER BY p.created_at DESC LIMIT 250");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Marketplace transactions</title><link href="../assets/css/main.css" rel="stylesheet"></head><body><?php include __DIR__ . '/../includes/header.php'; ?><main class="container-fluid py-4"><h1 class="h2">Marketplace transactions</h1><div class="row g-3 my-2"><div class="col-md-4"><div class="card card-body"><small>Successful orders</small><strong><?php echo (int)$totals['successful_count']; ?> · GHS <?php echo number_format(((int)$totals['gross_minor']) / 100, 2); ?> gross</strong></div></div><div class="col-md-4"><div class="card card-body"><small>Platform commission</small><strong>GHS <?php echo number_format(((int)$totals['commission_minor']) / 100, 2); ?></strong></div></div><div class="col-md-4"><div class="card card-body"><small>Pending / failed</small><strong><?php echo (int)$totals['pending_count']; ?> / <?php echo (int)$totals['failed_count']; ?></strong></div></div></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Date</th><th>Reference / Booking</th><th>Event</th><th>Attendee</th><th>Organizer</th><th>Payment / Booking status</th><th>Gross</th><th>Commission</th><th>Gateway fee</th><th>Organizer allocation</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?php echo htmlspecialchars($row['created_at']); ?></td><td><?php echo htmlspecialchars($row['transaction_reference'] . ' / ' . $row['booking_reference']); ?></td><td><?php echo htmlspecialchars($row['event_name']); ?></td><td><?php echo htmlspecialchars($row['attendee']); ?></td><td><?php echo htmlspecialchars($row['organizer']); ?></td><td><?php echo htmlspecialchars($row['status'] . ' / ' . $row['booking_status']); ?></td><td>GHS <?php echo number_format(((int)$row['gross_minor']) / 100, 2); ?></td><td>GHS <?php echo number_format(((int)$row['commission_minor']) / 100, 2); ?></td><td><?php echo $row['provider_fee_minor'] === null ? 'Pending' : 'GHS ' . number_format(((int)$row['provider_fee_minor']) / 100, 2); ?></td><td><?php echo $row['organizer_net_minor'] === null ? 'Pending' : 'GHS ' . number_format(((int)$row['organizer_net_minor']) / 100, 2); ?></td></tr><?php endforeach; ?></tbody></table></div><p class="small text-muted">Settlement records are not automatically synchronized; these are verified transaction allocations, not bank payout confirmations.</p></main><?php include __DIR__ . '/../includes/footer.php'; ?></body></html>
